<script setup lang="ts">
import { computed,nextTick,onBeforeUnmount,onMounted,ref,watch } from 'vue'
import { ApiError,describeError,mutationNeedsReadback,downloadFile,formatDate,request,workspacePath,type Workspace } from './api'
import { scenarioContextHref } from './scenario-context'
import { checkedDataCase,sameDataScope,dataCaseCreatePayload,dataCaseAIPreview,dataChannelLabels,dataEnforcementLabels,dataEndpointScopeLabels,dataEndpointStageLabels,type DataCase,type DataScope,type DataWindow } from './data-security'
import EndpointChannelsPanel from './EndpointChannelsPanel.vue'
import type { EndpointEventScope } from './endpoint-channels'
const props=defineProps<{workspace:Workspace}>();const emit=defineEmits<{sessionExpired:[]}>()
const base=workspacePath(props.workspace.slug),active=new AbortController(),editor=computed(()=>['owner','operator'].includes(props.workspace.role))
const sources=ref<{id:number;name:string;kind:string;revokedAt?:string}[]>([]),profiles=ref<{id:number;name:string;model:string;enabled:boolean;allowMetadata:boolean}[]>([])
const aiMode=ref<string|null>(null),loadingData=ref(false),casesLoaded=ref(false),casesReadAt=ref(''),windowReadAt=ref('')
const sourcesError=ref(''),casesError=ref(''),engineError=ref('')
let freezeEpoch=0
const readbackRequired=ref(new Set<number>()),freezeUncertain=ref(false),freezeChecked=ref(false)
const endpointChannelsOpen=ref(false),eventsPanel=ref<HTMLElement>(),panel=ref<HTMLElement>(),pageHeading=ref<HTMLElement>(),eventsHeading=ref<HTMLElement>(),freezeHeading=ref<HTMLElement>()
const sourceId=ref(0),subjectRef=ref(''),deviceRef=ref(''),channel=ref(''),from=ref(local(new Date(Date.now()-86400000))),to=ref(local(new Date())),title=ref(''),windowData=ref<DataWindow>(),cases=ref<DataCase[]>([]),selected=ref<DataCase>(),busy=ref(false),error=ref(''),notice=ref(''),feedback=ref('needs_investigation'),note=ref(''),profileId=ref(0),consent=ref(false)
const scopeChanged=computed(()=>{if(!windowData.value)return false;try{return !sameDataScope(windowData.value.scope,scope())}catch{return true}})
watch(profileId,()=>consent.value=false)
const selectedNeedsReadback=computed(()=>!!selected.value && readbackRequired.value.has(selected.value.id))
function local(d:Date){return new Date(d.getTime()+8*3600000).toISOString().slice(0,16)}
function scope():DataScope{return {sourceId:Number(sourceId.value),subjectRef:subjectRef.value.trim()||undefined,deviceRef:deviceRef.value.trim()||undefined,channel:channel.value||undefined,from:new Date(from.value+':00+08:00').toISOString(),to:new Date(to.value+':00+08:00').toISOString()}}
function focusScope(){return JSON.stringify([sourceId.value,subjectRef.value,deviceRef.value,channel.value,from.value,to.value])}
async function restoreDataFocus(trigger:Element|null,expectedScope:string,expectedCase:number|undefined,target:'page'|'events'|'freeze'){
  await nextTick()
  if(active.signal.aborted || !panel.value?.isConnected || busy.value || document.activeElement!==document.body || focusScope()!==expectedScope || selected.value?.id!==expectedCase)return
  if(trigger instanceof HTMLElement && panel.value.contains(trigger) && trigger.isConnected && !trigger.matches(':disabled'))trigger.focus({preventScroll:true})
  else if(target==='freeze' && freezeHeading.value?.isConnected)freezeHeading.value.focus({preventScroll:true})
  else if(target==='events' && eventsHeading.value?.isConnected)eventsHeading.value.focus({preventScroll:true})
  else pageHeading.value?.focus({preventScroll:true})
}
function failure(e:unknown){if(active.signal.aborted)return;if(e instanceof ApiError&&e.status===401){emit('sessionExpired');return};error.value=describeError(e)}
async function load(){
  if(loadingData.value)return
  const focusTrigger=document.activeElement,expectedScope=focusScope(),expectedCase=selected.value?.id
  const checkingFreeze=freezeUncertain.value,epoch=freezeEpoch;if(checkingFreeze)freezeChecked.value=false
  loadingData.value=true;sourcesError.value='';casesError.value='';engineError.value=''
  const results=await Promise.allSettled([request<{items:typeof sources.value}>(base+'/operations/sources',{signal:active.signal}).then(out=>{if(!out || !Array.isArray(out.items))throw new Error('列表响应缺少记录数组，原记录保持不变。');return out}),request<{items:DataCase[]}>(base+'/data-security/cases',{signal:active.signal}).then(out=>{if(!out || !Array.isArray(out.items))throw new Error('列表响应缺少记录数组，原记录保持不变。');return out}),request<{profiles:typeof profiles.value;settings:{mode:string}}>(base+'/classification/engine',{signal:active.signal}).then(out=>{if(!out || !Array.isArray(out.profiles) || !out.settings || !['local','hybrid'].includes(out.settings.mode))throw new Error('未取得有效引擎模式与模型选项。');return out})])
  if(active.signal.aborted)return
  const [a,b,c]=results
  if(a.status==='fulfilled')sources.value=a.value.items.filter(v=>v.kind==='security_events'&&!v.revokedAt);else{sourcesError.value=describeError(a.reason);if(a.reason instanceof ApiError&&a.reason.status===401)emit('sessionExpired')}
  if(b.status==='fulfilled'){cases.value=b.value.items;casesLoaded.value=true;casesReadAt.value=new Date().toISOString();if(checkingFreeze && epoch===freezeEpoch && freezeUncertain.value)freezeChecked.value=true}else{casesError.value=describeError(b.reason);if(b.reason instanceof ApiError&&b.reason.status===401)emit('sessionExpired')}
  if(c.status==='fulfilled'){profiles.value=c.value.profiles.filter(v=>v.enabled&&v.allowMetadata);aiMode.value=c.value.settings.mode;consent.value=false}else{engineError.value=describeError(c.reason);if(c.reason instanceof ApiError&&c.reason.status===401)emit('sessionExpired')}
  loadingData.value=false;await restoreDataFocus(focusTrigger,expectedScope,expectedCase,'page')
}
async function query(){
  if(busy.value)return
  const focusTrigger=document.activeElement,expectedScope=focusScope(),expectedCase=selected.value?.id
  busy.value=true;error.value='';notice.value=''
  try{const requested=scope(),q=new URLSearchParams();for(const [key,value] of Object.entries(requested))if(value!==undefined)q.set(key,String(value));const out=await request<DataWindow>(base+'/data-security/events?'+q,{signal:active.signal});if(active.signal.aborted)return;if(!out || !out.scope || !Array.isArray(out.items) || !Number.isSafeInteger(out.total))throw new Error('事件响应缺少有效范围、记录或计数，原结果保持不变。');if(!sameDataScope(requested,out.scope))throw new Error('返回事件范围与本次查询不一致，请重新读取；原查询结果保持不变。');windowData.value=out;windowReadAt.value=new Date().toISOString()}catch(e){failure(e)}finally{busy.value=false;await restoreDataFocus(focusTrigger,expectedScope,expectedCase,'events')}
}
async function inspectEndpointEvents(value:EndpointEventScope){if(busy.value){error.value='当前操作尚未结束，请稍后核对此设备事件。';return};sourceId.value=value.sourceId;deviceRef.value=value.deviceRef;subjectRef.value='';channel.value=value.channel||'';await query();await nextTick();eventsPanel.value?.scrollIntoView({block:'start'})}
async function freeze(){
  if(busy.value||!editor.value||!title.value.trim()||!windowData.value||freezeUncertain.value)return
  if(scopeChanged.value){error.value='筛选范围已变化，请先查询事件，再按已显示范围创建调查快照。';return}
  let payload:ReturnType<typeof dataCaseCreatePayload>
  try{payload=dataCaseCreatePayload(title.value,windowData.value,scope())}catch(e){failure(e);return}
  const focusTrigger=document.activeElement,expectedScope=focusScope()
  let expectedCase=selected.value?.id
  freezeEpoch++;busy.value=true;error.value='';freezeUncertain.value=true;freezeChecked.value=false
  try{selected.value=await request<DataCase>(base+'/data-security/cases',{method:'POST',body:JSON.stringify(payload),signal:active.signal});expectedCase=selected.value.id;freezeUncertain.value=false;consent.value=false;note.value='';await load();notice.value='已按上方已应用范围重新读取并冻结来源事件、关联关系和覆盖缺口；快照内容以服务端创建时点为准。'}catch(e){if(!mutationNeedsReadback(e,true))freezeUncertain.value=false;failure(e)}finally{busy.value=false;await restoreDataFocus(focusTrigger,expectedScope,expectedCase,'freeze')}
}
async function choose(id:number){
  if(busy.value)return
  const original=selected.value?.id===id?selected.value:undefined
  busy.value=true;error.value=''
  try{const received=await request<DataCase>(base+'/data-security/cases/'+id,{signal:active.signal});if(active.signal.aborted)return;selected.value=checkedDataCase(id,received,original);readbackRequired.value.delete(id);consent.value=false;if(!original)note.value='';notice.value=original?'已重新读取原调查及保存记录。请核对是否已经完成上次提交，再决定后续操作。':''}catch(e){failure(e)}finally{busy.value=false}
}
async function mutateCase(kind:'feedback'|'ai-reference',body:unknown){
  const original=selected.value
  if(!original||busy.value||readbackRequired.value.has(original.id))return
  busy.value=true;error.value='';notice.value='';readbackRequired.value.add(original.id)
  try{await request(base+'/data-security/cases/'+original.id+'/'+kind,{method:'POST',body:JSON.stringify(body),signal:active.signal});const received=await request<DataCase>(base+'/data-security/cases/'+original.id,{signal:active.signal});if(active.signal.aborted)return;selected.value=checkedDataCase(original.id,received,original);readbackRequired.value.delete(original.id);if(kind==='feedback')note.value='';notice.value=kind==='feedback'?'已保存人工反馈，未改写原始事件或自动关闭监管检查。':'模型参考已留存。请核对其引用的事件及不确定性，再决定如何处理。'}catch(e){if(kind==='feedback' && !mutationNeedsReadback(e,true))readbackRequired.value.delete(original.id);failure(e)}finally{consent.value=false;busy.value=false}
}
async function addFeedback(){if(!editor.value||!selected.value||!note.value.trim())return;await mutateCase('feedback',{decision:feedback.value,note:note.value.trim()})}
async function assess(){if(!editor.value||!selected.value||!consent.value||!profileId.value||aiMode.value!=='hybrid'||!!engineError.value||!profiles.value.some(p=>p.id===Number(profileId.value)))return;await mutateCase('ai-reference',{profileId:Number(profileId.value),allowMetadata:true,caseDigest:selected.value.snapshotDigest})}
async function exportCase(format:'html'|'json'){if(!selected.value||busy.value)return;busy.value=true;error.value='';try{await downloadFile(base+'/data-security/cases/'+selected.value.id+'/export?format='+format,`data-security-case-${selected.value.id}.${format}`,active.signal)}catch(e){failure(e)}finally{busy.value=false}}
function feedbackText(s:Record<string,unknown>){if(typeof s.note==='string')return s.note;const r=s.result;if(r&&typeof r==='object'&&'summary'in r&&typeof r.summary==='string')return r.summary;return '查看保存的参考记录'}
onMounted(()=>{void load()});onBeforeUnmount(()=>active.abort())
</script>
<template><section ref="panel" class="data-security-panel"><header><h2 ref="pageHeading" tabindex="-1">数据外发与事件调查</h2><p>按来源核对终端、数据库与 AI 使用事件，将关联证据冻结成调查快照。敏感正文、SQL、提示词和真实身份留在源端。</p><a class="table-link" :href="scenarioContextHref(workspace.slug,'operations')">登记或管理安全事件来源</a></header>
<p v-if="loadingData" class="message" role="status">正在读取来源、调查记录和引擎配置…</p><p v-if="sourcesError" class="message message-error" role="alert">来源选项未刷新：{{sourcesError}}<button class="button button-secondary" :disabled="loadingData || busy" @click="load">重试读取</button></p><p v-if="engineError" class="message message-error" role="alert">引擎配置未刷新：{{engineError}} 当前不能确认可用参考模型。<button class="button button-secondary" :disabled="loadingData || busy" @click="load">重试引擎配置</button></p>
<p v-if="error" class="message message-error" role="alert">{{error}}</p><p v-if="notice" class="message message-success" role="status">{{notice}}</p>
<section class="panel"><div class="panel-heading"><div><h3>USB、打印与剪贴板</h3><p>核对已接入设备的真实能力，再登记通道策略、独立审批和源端回执。</p></div><button class="button" type="button" :aria-expanded="endpointChannelsOpen" aria-controls="endpoint-channels" @click="endpointChannelsOpen=!endpointChannelsOpen">{{endpointChannelsOpen?'收起设备与策略':'查看设备与通道策略'}}</button></div></section>
<EndpointChannelsPanel v-if="endpointChannelsOpen" id="endpoint-channels" :workspace="workspace" @session-expired="emit('sessionExpired')" @inspect-events="inspectEndpointEvents" />
<details class="panel source-guide"><summary>接入与覆盖范围</summary><p>现有事件桥接支持受授权的规范化 DLP 投影、Wazuh 文件变更和 PostgreSQL pgAudit 日志。原有未携带数据上下文的告警不会被补造成终端事件。</p><p>源端策略 SDK 可检查指定通道、保护类别和批准的 AI 域名；受控文本复制工具会实际拒绝被策略阻止的复制。USB、打印、剪贴板等通道须由对应终端工具提供真实事件和执行证据，此页面不会自行取得这些通道的系统权限。</p><p>调查只关联同一来源内相同主体或设备引用。来源声称阻断、实际执行、自动复测和独立复核分别核验。</p></details>
<form class="panel data-filter" @submit.prevent="query"><label>安全事件来源<select v-model.number="sourceId" :disabled="busy"><option :value="0">工作区全部已接入来源</option><option v-for="s in sources" :key="s.id" :value="s.id">{{s.name}} · #{{s.id}}</option></select></label><label>数据通道<select v-model="channel" :disabled="busy"><option value="">全部已记录通道</option><option v-for="(label,key) in dataChannelLabels" :key="key" :value="key">{{label}}</option></select></label><label>主体引用（可选）<input v-model="subjectRef" pattern="[0-9a-f]{64}" placeholder="客户侧 HMAC 引用，不填写姓名或账号" :disabled="busy"></label><label>设备引用（可选）<input v-model="deviceRef" pattern="[0-9a-f]{64}" placeholder="客户侧 HMAC 引用" :disabled="busy"></label><label>开始时间（上海）<input v-model="from" type="datetime-local" required :disabled="busy"></label><label>结束时间（上海）<input v-model="to" type="datetime-local" required :disabled="busy"></label><div class="actions"><button class="button button-primary" :disabled="busy">{{busy?'正在处理…':'查询已记录事件'}}</button></div></form>
<section v-if="windowData" ref="eventsPanel" class="panel"><div class="panel-heading"><div><h3 ref="eventsHeading" tabindex="-1">已读取来源事件 · {{windowData.items.length}} / {{windowData.total}}</h3><p>最多纳入200条，{{windowData.truncated?'本次已截断，超出部分未知':'本次未达到条数上限'}}。没有事件不证明通道未使用或没有风险。</p></div></div><div class="event-applied-scope"><p>已应用：{{windowData.scope.sourceId?'来源 #'+windowData.scope.sourceId:'工作区全部已接入来源'}} · {{dataChannelLabels[windowData.scope.channel || ''] || '全部已记录通道'}} · {{formatDate(windowData.scope.from)}} 至 {{formatDate(windowData.scope.to)}}。读取于 {{formatDate(windowReadAt,true)}}。</p><p v-if="scopeChanged" class="message message-warning" role="status">上方筛选尚未应用，下方保留已读取范围。重新查询后才能据此创建调查快照。</p></div><p v-if="!windowData.items.length" class="message">当前范围没有携带数据上下文的事件。请先接入对应来源，或核对来源和时间范围。</p><div v-else class="table-scroll" role="region" aria-label="已应用范围的数据来源事件" tabindex="0"><table class="data-table"><thead><tr><th scope="col">观察 / 来源</th><th scope="col">通道与操作</th><th scope="col">主体 / 设备引用</th><th scope="col">对象与去向</th><th scope="col">来源结果 / 检查</th></tr></thead><tbody><tr v-for="e in windowData.items" :key="e.id"><th scope="row"><time class="table-date" :datetime="e.observedAt" :title="e.observedAt">{{formatDate(e.observedAt)}}</time><small>{{e.source}} · #{{e.id}}</small><small>{{e.sourceCurrent?'来源当前有效':'历史来源已失效'}}</small></th><td>{{dataChannelLabels[e.dataContext.channel]||e.dataContext.channel}}<small>{{e.dataContext.operation}} · {{e.rule}}</small></td><td><code>{{e.dataContext.subjectRef || '未记录主体'}}<small>{{e.dataContext.deviceRef || '未记录设备'}}</small></code></td><td><code>{{e.dataContext.fileDigest || e.dataContext.objectRef || '未记录对象'}}</code><small>{{e.dataContext.destinationDomain||'未记录目的地域名'}}</small><small>{{e.dataContext.categories.join('、')||'未取得内容类别'}}</small></td><td>{{dataEnforcementLabels[e.dataContext.enforcement]}}<template v-if="e.dataContext.endpoint"><small>{{dataEndpointScopeLabels[e.dataContext.endpoint.scope]||e.dataContext.endpoint.scope}} · {{dataEndpointStageLabels[e.dataContext.endpoint.stage]||e.dataContext.endpoint.stage}}</small><small v-if="e.dataContext.endpoint.policyId">策略 #{{e.dataContext.endpoint.policyId}} · v{{e.dataContext.endpoint.policyRevision}}</small><small v-if="e.dataContext.endpoint.scope==='observation'">观察变化不等于预先阻断</small></template><small>{{e.dataContext.capture==='complete'?'来源声明投影完整':'投影不完整，未观察部分未知'}}</small><a v-if="e.checkId" class="table-link" :href="scenarioContextHref(workspace.slug,'checks/'+e.checkId)">关联检查 #{{e.checkId}}</a><small v-else>活动审计，不创建风险检查</small></td></tr></tbody></table></div></section>
<form v-if="editor" class="panel case-form" @submit.prevent="freeze"><h3 ref="freezeHeading" tabindex="-1">冻结调查证据</h3><p>至少需要一条已读取事件，才能创建调查快照。</p><p>采用上方已成功读取的范围，在创建时重新读取事件并保存来源、原始编号、关联关系和截断情况；不是当前列表的逐字冻结，后续反馈不会改写快照。</p><label>调查名称<input v-model="title" required maxlength="120" :disabled="busy" placeholder="例如：指定来源的敏感文件外发调查"></label><button class="button button-primary" :disabled="busy||!title.trim()||!windowData?.items.length||scopeChanged||freezeUncertain">生成调查快照</button></form><div v-if="freezeUncertain" class="message message-warning" role="status"><p>创建结果尚未核实，不能视为没有创建。请重新读取调查记录，核对是否已有本次快照。</p><button class="button button-secondary" :disabled="busy || loadingData" @click="load">重新读取调查记录</button><button v-if="freezeChecked" class="button button-secondary" :disabled="busy || loadingData" @click="freezeUncertain=false;freezeChecked=false">已核对记录，准备另一份快照</button></div>
<section class="panel"><div class="panel-heading"><div><h3>已读取调查记录{{casesLoaded?' · '+cases.length:''}}</h3><p>每份调查的采用范围以其保存快照为准。{{casesReadAt?'本列表读取于 '+formatDate(casesReadAt,true)+'。':'尚未成功读取调查列表。'}}</p></div><button class="button" :disabled="busy || loadingData" @click="load">刷新记录与配置</button></div><p v-if="casesError" class="message message-error" role="alert">{{casesError}}{{casesLoaded?' 保留上次成功读取的记录，本次列表未更新。':' 记录数量未知，请重试读取。'}}</p><p v-if="casesLoaded && !cases.length && !casesError" class="message">尚无调查快照。先选择真实来源与窗口，再冻结可核对的事件。</p><ul v-if="cases.length" class="case-list"><li v-for="c in cases" :key="c.id"><button class="button" :disabled="busy" :aria-pressed="selected?.id===c.id" @click="choose(c.id)">{{c.title}} · #{{c.id}}</button><span>{{formatDate(c.createdAt)}} · {{c.actor}}</span></li></ul></section>
<section v-if="selected" class="panel case-detail"><div class="panel-heading"><div><h3>{{selected.title}} · #{{selected.id}}</h3><p>{{formatDate(selected.scope.from)}} 至 {{formatDate(selected.scope.to)}}</p></div><div class="actions"><button class="button" :disabled="busy" @click="exportCase('html')">导出调查 HTML</button><button class="button" :disabled="busy" @click="exportCase('json')">导出调查 JSON</button></div></div><div class="case-body"><p v-if="selectedNeedsReadback" class="message message-warning" role="status">上次提交结果尚未核实，请先重新读取本调查及其保存记录；读取失败不会解锁提交，反馈草稿保留。</p><button class="button button-secondary" :disabled="busy" @click="choose(selected.id)">重新读取当前快照与记录</button><h4>同来源事件关联</h4><article v-for="(chain,index) in selected.snapshot.chains" :key="index"><strong>关联证据组 {{index+1}} · 来源 #{{chain.sourceId}}</strong><p>{{chain.summary}}</p><p>{{chain.channels.map(c=>dataChannelLabels[c]||c).join('、')}} · 事件 {{chain.eventIds.map(id=>'#'+id).join('、')}}</p></article><h4>覆盖与未知条件</h4><ul><li v-for="v in selected.snapshot.coverage" :key="v">{{v}}</li></ul><small>冻结摘要 {{selected.snapshotDigest}}</small>
<form v-if="editor && selected.notes.length<200" class="case-form" @submit.prevent="addFeedback"><h4>人工研判反馈</h4><label>反馈类别<select v-model="feedback" :disabled="busy"><option value="needs_investigation">继续调查</option><option value="expected_activity">符合已核对业务预期</option><option value="false_positive">已核对为误报</option></select></label><label>核对依据<textarea v-model="note" required maxlength="600" rows="3" :disabled="busy"></textarea></label><button class="button" :disabled="busy||!note.trim()||selectedNeedsReadback">保存反馈</button></form>
<p v-if="editor && aiMode===null">引擎模式尚未读取，当前不能确认是否可用 AI 参考。请刷新引擎配置后核对。</p><p v-if="editor && aiMode==='local'">当前已读取的引擎模式仅使用本地能力。可先在分类分级的“识别引擎与 AI”配置中明确启用混合模式，再选择运营参考模型。</p><form v-if="editor && aiMode==='hybrid' && selected.notes.length<200" class="case-form" @submit.prevent="assess"><h4>可选 AI 运营参考</h4><p>仅发送下方预览的事件类别、规则、执行声明与链编号，不发送主体/设备引用、文件摘要、路径、SQL或提示词。模型结论不自动处置或关闭检查。</p><details><summary>查看将发送的事件投影</summary><pre>{{JSON.stringify(dataCaseAIPreview(selected),null,2)}}</pre></details><label>选择运营参考模型<select v-model.number="profileId" :disabled="busy"><option :value="0">请选择已启用且允许元数据的模型</option><option v-for="p in profiles" :key="p.id" :value="p.id">{{p.name}} · {{p.model}}</option></select></label><label class="consent"><input v-model="consent" type="checkbox" :disabled="busy||!profileId">允许向所选模型发送预览投影，用于本次参考研判（可能产生费用）</label><button class="button" :disabled="busy||!consent||!profileId||selectedNeedsReadback||!!engineError||selected.snapshot.window.items.length>100">生成运营参考</button><p v-if="selected.snapshot.window.items.length>100">模型参考最多采用100条事件，请缩小范围后生成新快照。</p></form>
<p v-if="selected.notes.length>=200">这份调查已达到反馈与参考记录预算。请保留导出，在后续调查中继续记录，原证据保持留存。</p><h4>反馈与模型参考记录</h4><p v-if="!selected.notes.length">尚无反馈或模型参考。</p><article v-for="n in selected.notes" :key="n.id"><strong>{{n.kind==='feedback'?'人工反馈':'AI 参考 · 未自动采用'}}</strong><p>{{feedbackText(n.snapshot)}}</p><small>{{n.actor}} · {{formatDate(n.createdAt)}}</small><details><summary>核对完整保存记录</summary><pre>{{JSON.stringify(n.snapshot,null,2)}}</pre></details></article></div></section></section></template>
<style scoped>
