.event-applied-scope{padding:14px 20px;border-bottom:1px solid var(--line);background:var(--surface-subtle)}.event-applied-scope p{margin:0}.event-applied-scope p+p{margin-top:10px}.data-security-panel .message button{margin:10px 8px 0 0}.data-security-panel :is(summary,[tabindex],button,input,select,textarea):focus-visible{outline:3px solid var(--accent);outline-offset:3px}.case-list button[aria-pressed=true]{background:var(--accent-soft);border-color:var(--accent);color:var(--accent)}
</style>
